### ✅ **Solution: Convert `ptake` to a numeric matrix**

You need to convert the cell array `ptake` into a numeric matrix before performing any numeric operations like `sum`.

Here's the corrected version of your function:

```matlab
function [ucost, ttake] = takeoff(ptake, ftake, materials)
    % Convert ptake to a numeric matrix
    ptake = cell2mat(ptake);

    if size(ptake,1) < 2
        ttake = "Info is not enough";
        ucost = NaN;
        return
    end

    % Calculate unit cost
    % Take all rows except the last one (total cost column)
    quantities = ptake(1:end-1, 1:end-1);
    total_costs = ptake(1:end-1, end);

    ucost = sum(quantities, 1) ./ sum(total_costs, 1);

    % Calculate total cost for future months
    ftake = cell2mat(ftake);
    total_cost_ftake = ftake(:, 1:end-1) * ucost';

    % Combine past and future quantities
    all_quantities = [ptake(:, 1:end-1); ftake(:, 1:end-1)];

    % Combine past and future total costs
    total_cost_ptake = ptake(:, end);
    total_cost_ftake = total_cost_ftake(:); % Ensure it's a column vector

    % Create the final ttake cell array
    % First row: materials
    ttake = [materials', num2cell(all_quantities, 2), num2cell([total_cost_ptake, total_cost_ftake], 2)];

    % Add the "cost" row
    cost_row = ["cost", "", "", "", num2cell([sum(total_cost_ptake), sum(total_cost_ftake)])];
    ttake = [ttake; cost_row];
end
